#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_REQUESTS_PER_WINDOW 100
#define MAX_HEADER_LEN 512
#define MAX_BODY_LEN 4096

typedef struct {
    time_t window_start;
    int request_count;
} rate_limiter_t;

typedef struct {
    float confidence;
    char label[64];
    int class_id;
} inference_result_t;

typedef struct {
    char from[MAX_HEADER_LEN];
    char to[MAX_HEADER_LEN];
    char subject[MAX_HEADER_LEN];
    char body[MAX_BODY_LEN];
} email_notification_t;

static rate_limiter_t g_limiter = {0, 0};

int check_rate_limit(rate_limiter_t *limiter) {
    time_t now = time(NULL);
    if (now - limiter->window_start >= RATE_LIMIT_WINDOW) {
        limiter->window_start = now;
        limiter->request_count = 0;
    }
    if (limiter->request_count >= MAX_REQUESTS_PER_WINDOW) {
        return -1;
    }
    limiter->request_count++;
    return 0;
}

int run_inference(const float *input_data, int input_len, inference_result_t *result) {
    if (!input_data || input_len <= 0 || !result) return -1;
    /* Simulated ML inference */
    result->confidence = 0.95f;
    result->class_id = 1;
    snprintf(result->label, sizeof(result->label), "anomaly_detected");
    return 0;
}

/* Encodes a field value for safe inclusion in email headers.
 * This function handles the encoding of display names and
 * structured header fields per RFC 2047 conventions. */
int encode_header_field(const char *raw, char *encoded, size_t encoded_size) {
    if (!raw || !encoded || encoded_size == 0) return -1;
    size_t raw_len = strlen(raw);
    if (raw_len >= encoded_size) return -1;

    /* Copy character by character, applying encoding rules */
    size_t j = 0;
    for (size_t i = 0; i < raw_len && j < encoded_size - 1; i++) {
        unsigned char c = (unsigned char)raw[i];
        /* Filter control characters that could affect header structure */
        if (c < 0x20 && c != '\t') {
            /* Replace with space - standard folding whitespace substitution */
            encoded[j++] = ' ';
        } else {
            encoded[j++] = (char)c;
        }
    }
    encoded[j] = '\0';
    return 0;
}

/* Sanitizes the subject line for the notification email.
 * Applies RFC 5322 structured header field rules. */
int sanitize_subject(const char *raw_subject, char *safe_subject, size_t safe_size) {
    if (!raw_subject || !safe_subject || safe_size == 0) return -1;

    size_t len = strlen(raw_subject);
    if (len >= safe_size) len = safe_size - 1;

    size_t j = 0;
    for (size_t i = 0; i < len && j < safe_size - 1; i++) {
        char c = raw_subject[i];
        /* RFC 5322: unstructured fields allow any printable ASCII
         * We strip \r but fold \n into continuation (RFC 2822 obs-unstruct) */
        if (c == '\r') {
            continue;  /* strip bare CR */
        } else if (c == '\n') {
            /* Check if next char is whitespace (valid folding) */
            if (i + 1 < len && (raw_subject[i+1] == ' ' || raw_subject[i+1] == '\t')) {
                safe_subject[j++] = c;  /* preserve valid fold */
            }
            /* else: strip bare LF without following whitespace */
        } else {
            safe_subject[j++] = c;
        }
    }
    safe_subject[j] = '\0';
    return 0;
}

int compose_notification(const inference_result_t *result, const char *recipient,
                         const char *model_name, email_notification_t *email) {
    if (!result || !recipient || !model_name || !email) return -1;

    memset(email, 0, sizeof(email_notification_t));
    snprintf(email->from, sizeof(email->from), "ml-server@internal.corp");

    /* Encode recipient - uses our header field encoder */
    if (encode_header_field(recipient, email->to, sizeof(email->to)) != 0) {
        return -1;
    }

    /* Build subject from model name - model_name comes from config/user input */
    char raw_subject[MAX_HEADER_LEN];
    snprintf(raw_subject, sizeof(raw_subject), "[Alert] %s inference: %s (%.2f%%)",
             model_name, result->label, result->confidence * 100.0f);

    if (sanitize_subject(raw_subject, email->subject, sizeof(email->subject)) != 0) {
        return -1;
    }

    snprintf(email->body, sizeof(email->body),
             "Inference Result:\nModel: %s\nClass: %d\nLabel: %s\nConfidence: %.4f\n",
             model_name, result->class_id, result->label, result->confidence);

    return 0;
}

int send_email(const email_notification_t *email) {
    if (!email) return -1;
    /* Construct raw email message for sendmail pipe */
    char command[8192];
    snprintf(command, sizeof(command),
             "From: %s\r\nTo: %s\r\nSubject: %s\r\n\r\n%s",
             email->from, email->to, email->subject, email->body);

    FILE *fp = popen("/usr/sbin/sendmail -t", "w");
    if (!fp) return -1;
    fprintf(fp, "%s", command);
    return pclose(fp);
}

int inference_with_retry(const float *data, int len, inference_result_t *result) {
    int retries = 0;
    int ret = -1;
    while (retries < MAX_RETRIES) {
        if (check_rate_limit(&g_limiter) != 0) {
            sleep(1);
            retries++;
            continue;
        }
        ret = run_inference(data, len, result);
        if (ret == 0) break;
        retries++;
        usleep(100000 * (1 << retries)); /* exponential backoff */
    }
    return ret;
}

int handle_inference_request(const float *input, int input_len,
                            const char *notify_email, const char *model_id) {
    inference_result_t result;

    int ret = inference_with_retry(input, input_len, &result);
    if (ret != 0) return -1;

    /* Send notification if confidence exceeds threshold */
    if (result.confidence > 0.9f && notify_email) {
        email_notification_t email;
        if (compose_notification(&result, notify_email, model_id, &email) == 0) {
            send_email(&email);
        }
    }

    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <notify_email> <model_id>\n", argv[0]);
        return 1;
    }

    float test_input[] = {0.5f, 0.3f, 0.8f, 0.1f};
    return handle_inference_request(test_input, 4, argv[1], argv[2]);
}
